//! The frozen eid-circuits circuits.
//!
//! [`circuits`] is generated by `build.rs` from `circuits/manifest.toml` and
//! `resources/` (written by `cargo xtask freeze-circuits`): per active
//! circuit, typed inputs, a marker implementing
//! [`Circuit`](noir_zk_core::Circuit) and [`CircuitId`](noir_zk_core::CircuitId)
//! (with its Chonk verification key embedded), plus [`circuits::REGISTRY`]
//! over every version and the verification key tree root.
//!
//! Bytecode isn't embedded (about 750 MB for all circuits): [`Canonical`]
//! fetches it from an [`ArtifactStore`] and rejects it unless it hashes to the
//! pinned value. Verification needs no bytecode: [`hiding_vk`] and
//! [`vk_tree_root`] are all a verifier pins.

pub mod store;

use std::collections::HashMap;
use std::sync::Mutex;

use sha2::{Digest, Sha256};

use noir_zk_core::codec::field_from_be_bytes_canonical;
use noir_zk_core::{Artifacts, CircuitKind, Error, Field, VkPath};

#[cfg(feature = "http")]
pub use store::HttpStore;
pub use store::{ArtifactStore, DirStore};

/// Lifecycle of a frozen circuit version.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Status {
    /// Proves and verifies.
    Active,
    /// Superseded: its key is kept, its ABI dropped.
    Deprecated,
}

/// One frozen circuit version.
#[derive(Clone, Copy, Debug)]
pub struct RegistryEntry {
    /// Circuit package name.
    pub label: &'static str,
    /// Frozen version.
    pub version: &'static str,
    /// How Chonk folds it.
    pub kind: CircuitKind,
    /// Lifecycle status.
    pub status: Status,
    /// SHA-256 of the base64 bytecode (the release asset's content).
    pub bytecode_sha256: [u8; 32],
    /// nargo's ABI JSON (active versions only).
    pub abi: Option<&'static str>,
    /// Chonk verification key.
    pub vk: &'static [u8],
    /// Leaf index in the verification key tree (active, non-hiding circuits).
    pub vk_index: Option<u64>,
    /// Tree siblings from the leaf up (big-endian field elements).
    pub vk_siblings: &'static [[u8; 32]],
}

impl RegistryEntry {
    /// Release asset name of this version's bytecode.
    pub fn asset_name(&self) -> String {
        format!("{}@{}.b64", self.label, self.version)
    }
}

/// Generated from the frozen registry (see the crate docs).
#[allow(missing_docs, clippy::all)]
pub mod circuits {
    include!(concat!(env!("OUT_DIR"), "/circuits.rs"));
}

/// The active version of a circuit.
pub fn active(label: &str) -> Option<&'static RegistryEntry> {
    circuits::REGISTRY
        .iter()
        .find(|e| e.label == label && e.status == Status::Active)
}

/// The hiding kernel's verification key: every document proof verifies under it.
pub fn hiding_vk() -> &'static [u8] {
    active("kernel_hiding").map_or(&[], |e| e.vk)
}

/// The verification key tree root a document proof must carry.
pub fn vk_tree_root() -> Field {
    field(&circuits::VK_TREE_ROOT)
}

fn field(b: &[u8; 32]) -> Field {
    field_from_be_bytes_canonical(b, "registry field").unwrap_or_default()
}

/// The frozen circuits with bytecode from `S`, as the prover's [`Artifacts`].
pub struct Canonical<S: ArtifactStore> {
    store: S,
    cache: Mutex<HashMap<&'static str, String>>,
}

impl<S: ArtifactStore> Canonical<S> {
    /// Circuits whose bytecode comes from `store`.
    pub fn new(store: S) -> Self {
        Self {
            store,
            cache: Mutex::default(),
        }
    }

    fn entry(name: &str) -> Result<&'static RegistryEntry, Error> {
        active(name).ok_or_else(|| Error::Artifact(format!("no active circuit {name}")))
    }
}

impl<S: ArtifactStore> Artifacts for Canonical<S> {
    fn bytecode_b64(&self, name: &str) -> Result<String, Error> {
        let e = Self::entry(name)?;
        if let Some(b) = self
            .cache
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .get(e.label)
        {
            return Ok(b.clone());
        }
        let bytes = self.store.fetch(&e.asset_name())?;
        if Sha256::digest(&bytes).as_slice() != e.bytecode_sha256 {
            return Err(Error::Artifact(format!(
                "{}: bytecode does not match its pinned hash",
                e.asset_name()
            )));
        }
        let b64 = String::from_utf8(bytes)
            .map_err(|_| Error::Artifact(format!("{}: not base64 text", e.asset_name())))?;
        self.cache
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .insert(e.label, b64.clone());
        Ok(b64)
    }

    fn abi_json(&self, name: &str) -> Result<String, Error> {
        Self::entry(name)?
            .abi
            .map(str::to_string)
            .ok_or_else(|| Error::Artifact(format!("{name}: no ABI")))
    }

    fn vk(&self, name: &str) -> Result<Vec<u8>, Error> {
        Ok(Self::entry(name)?.vk.to_vec())
    }

    fn vk_path(&self, name: &str) -> Result<VkPath, Error> {
        let e = Self::entry(name)?;
        let index = e
            .vk_index
            .ok_or_else(|| Error::Artifact(format!("{name} is not in the key tree")))?;
        Ok(VkPath {
            index,
            siblings: e.vk_siblings.iter().map(field).collect(),
        })
    }

    fn vk_tree_root(&self) -> Field {
        vk_tree_root()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use noir_zk_core::{Circuit, CircuitId};

    #[test]
    fn registry_is_complete() {
        let active: Vec<_> = circuits::REGISTRY
            .iter()
            .filter(|e| e.status == Status::Active)
            .collect();
        assert_eq!(active.len(), 301);
        assert_eq!(
            active
                .iter()
                .filter(|e| e.kind == CircuitKind::Kernel)
                .count(),
            4
        );
        assert_eq!(
            active
                .iter()
                .filter(|e| e.kind == CircuitKind::Hiding)
                .count(),
            1
        );
        assert!(active
            .iter()
            .all(|e| e.kind == CircuitKind::Hiding || e.vk_index.is_some()));
        assert!(!hiding_vk().is_empty());
    }

    #[test]
    fn generated_types_flatten_to_the_abi_size() {
        use circuits::kernel_tail::{Inputs, KernelTail, MerklePath, Vk};
        let w = Inputs {
            prev: [Field::from(1u64); 26],
            prev_vk: Vk {
                key: [Field::from(2u64); 151],
                path: MerklePath {
                    index: Field::from(3u64),
                    siblings: [Field::from(4u64); 9],
                },
            },
        };
        let v = KernelTail::witness_inputs(&w, &());
        assert_eq!(v.len(), 26 + 151 + 1 + 9);
        assert_eq!(
            (v[0], v[26], v[26 + 151], v[26 + 152]),
            (1u64, 2, 3, 4).into_fields()
        );
        assert_eq!(KernelTail::LABEL, "kernel_tail");
        assert_eq!(KernelTail::KIND, CircuitKind::Kernel);
        assert_eq!(KernelTail::VK_BYTES, active("kernel_tail").unwrap().vk);
    }

    trait IntoFields {
        fn into_fields(self) -> (Field, Field, Field, Field);
    }
    impl IntoFields for (u64, u64, u64, u64) {
        fn into_fields(self) -> (Field, Field, Field, Field) {
            (self.0.into(), self.1.into(), self.2.into(), self.3.into())
        }
    }
}
